#!/usr/bin/env python3
"""mkrows.py > rows.md : the ledger rows of area 3 round 12 (A3-89 and up), fixture words assembled from the .src files beside this script.
Every cell is checked for an unescaped pipe; every row has eight cells."""
import os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import srcwords as sw
D = os.path.dirname(os.path.abspath(__file__))
_cache = {}
def blocks(path):
    if path not in _cache:
        _cache[path] = sw.blocks(os.path.join(D, path))
    return _cache[path]
def fx(path, prefix, addr='06009000'):
    for b in blocks(path):
        if b['name'].startswith(prefix):
            for a, w in b['asm']:
                if a == addr:
                    return '{ ' + ', '.join('0x%04X' % x for x in w) + ' }'
    raise KeyError((path, prefix, addr))
def cf(path, prefix):
    """CallFixture text with the entry and every callee (each lent unless the fixture says otherwise)"""
    for b in blocks(path):
        if b['name'].startswith(prefix):
            parts = ['`CallFixture { 0x06009000, %s }`' % fx(path, prefix)]
            lend = b['lend'].split()
            for a, w in b['asm'][1:]:
                words = '{ ' + ', '.join('0x%04X' % x for x in w) + ' }'
                parts.append('the function at 0x%s `%s`%s' % (a, words, ' (lent)' if a in lend else ' (not lent)'))
            return ' with '.join(parts[:1]) + ((' with ' + ', '.join(parts[1:])) if len(parts) > 1 else '')
    raise KeyError((path, prefix))
rows = []
def row(id_, sev, finding, fixture, status='open', found='area 3 round 12 review', closed=''):
    for cell in (finding, fixture, status, found, closed):
        assert not re.search(r'(?<!\\)\|', cell), cell[:100]
    rows.append('| %s | 3 | %s | %s | %s | %s | %s | %s |' % (id_, sev, finding, fixture, status, found, closed))

CTRL = "`func_0x06009040(&iStack_8); return axStack_18[0];`-like, the local (A3-71a's text, which holds when the callee is handed the frame address directly)"

row('A3-89', 'P1',
    "A frame address a callee keeps is lost. Patch 0061 (`FrameEscape`) follows a frame address through the function's own ops, its own STOREs ((b)) and the output of a call it is an input of ((d)), and the host's `storesBelow` loop reads registers; neither sees a pointer a CALLEE wrote to memory. The call is no STORE of the function; once the stack is heritaged, the slot the callee was given a pointer to is the INDIRECT output of the call, which is no member of the post-heritage walk (`FrameEscape::compute(fd, spc, false)`, run by `AliasChecker::gatherInternal` and `reprocessFreeStores`), so `escaped` stays false, the alias boundary stays at the address that was passed, and the INDIRECTs of the walk's stores on the locals below it are collapsed; and the host's only record of it, `CallEffects::leaks`, sets `State::escaped` (what a later `Loaded` carries) and nothing the engine reads (`mEscaped` is set by a call's `storesBelow`/`storesThrough` registers and by the probe, never by a leak). So a frame address handed to a call that stores it -- in a global (a software stack's `init(top)`, a registered buffer) or through a second argument into a slot of the caller's frame (`get_cursor(&cur, buf_end)`) -- and a later step that reads it back, in the caller or in a second callee that reads the global, and stores below it (a pre-decrement walk, `*--p = v`, a negative displacement) writes the locals under the address the engine took to be reached only at and above it, and they are folded: lent, `return 5;`, the code returns 1. Five ways, one cause: (a) a lent g stores r4 to a global, a lent h loads the global and walks down from it; (b) the same with g not lent (the caller is withheld, the text stale); (c) a lent g stores its second argument through its first, a slot of the caller's frame, and the caller reloads the slot and walks down (loop) or stores at a constant negative displacement; (d) a lent g stores r4 to a global and a lent g2 returns the global in r0 (`return_global`), the caller walks down from r0 -- the call's output of a call it was NOT handed the address in, which clause (d) of 0061 does not cover; (e) an unlent captured callee that writes its own frame's word at its entry r15 + 4 with the address (`mov.l r4,@(4,r15)`, the caller's outgoing word), reloaded by the caller (the caller is withheld, the text stale). The shape is compiled: a stack-like container whose top is given at init, an out-parameter that receives a pointer into a buffer. Current (a): `xunknown4 func_0x06009000(void) { xunknown1 axStack_8 [4]; func_0x06009040(axStack_8); func_0x06009080(); return 5; }`, lent (known, 0 parameters); (c): `func_0x06009040(&piStack_4,axStack_8); iVar1 = 4; do { piStack_4 = piStack_4 + -1; *piStack_4 = iVar1; iVar1 = iVar1 + -1; } while (iVar1 != 0); return 5;`, lent. The emulator returns 1 (the walk reaches the sentinel at r15 + 0). Expected: the control's, " + CTRL + ". Oracle: `PseudoAgreesWithRun` rejects (a: \"returns 00000005\"; the loops of c are beyond its evaluator, the run says 1). The walk fuzzer `tools/a3_round12/walkfuzz3.py` (a frame address persisted by a callee through a global or an out-parameter slot, then walked down in the caller or in a second callee, 14 laundering steps and four walk forms before it): 796 of 796 programs stale in four seeds (459 of them lent), with the direct hand-over as the control 0 of 103 in three seeds (`CONTROL=1`); the generator draws none of it (`GenLaunderWalkFn`'s global step is a round trip inside one function). **Fix direction (not a fix):** for (c) and (e) the engine's post-heritage walk should take a stack word defined by the INDIRECT of a call that was handed a member as an unmodeled member (a diagnostic build of the review that adds every stack word defined by an INDIRECT to that walk prints `return xStack_18;` for c, with the store left marked or not; the same build leaves a, b, d unchanged). For the global (a, b, d) the engine has nothing to see: the host knows what a lent callee does with an address (`leaks`, `storesThrough` memory, `frameValues`), so a call whose callee leaks a value of stack origin (`map(e.leaks & ~kStack) & kStack`, the line that sets `State::escaped`) must also declare the host alias from the frame's lowest slot (`mEscaped`, `mEscapedLow`) when the function later calls a callee that stores through memory or reads memory it does not track; a callee that stores through a pointer it loaded from memory needs a `storesBelow` bit for memory, which the caller reads against `State::escaped`. Every one of these costs precision where a function passes the address of a local to a callee that keeps it; to be measured on the corpora.",
    "**a** " + cf('r12a.src', 'C1a') + " (g: `mov.l @(lit),r1 ; mov.l r4,@r1`; h: `mov.l @(lit),r1 ; mov.l @r1,r1 ; mov #4,r2 ; L: mov.l r2,@-r1 ; dt r2 ; bf L ; rts ; nop`, the global 0x0600F100; the caller `sts.l pr,@-r15 ; add #-20,r15 ; mov #5,r0 ; mov.l r0,@r15 ; mov r15,r4 ; add #16,r4 ; jsr g ; jsr h ; mov.l @r15,r0 ; ...`). **b** " + cf('r12a.src', 'C1b') + ". **c** (the caller keeps PR in r8 so the walk cannot reach a saved PR) " + cf('r12b.src', 'C4a') + " (g: `rts ; mov.l r5,@r4`; the caller passes r4 = r15 + 20, a slot, and r5 = r15 + 16, the frame address); the same caller with the loop replaced by `add #-16,r1 ; mov.l r2,@r1` " + cf('r12b.src', 'C4c') + ". **d** " + cf('r12h.src', 'RG') + ". **e** " + cf('r12h.src', 'SH') + ". Replay: `OUT=<dir> sh tools/a3_round12/run.sh r12a.src` (and r12b, r12h; `bdrv.sh` builds the driver, `mk.py` assembles); `OUT=<dir> CONTROL=1 python3 walkfuzz3.py <seed> 200`.")

row('A3-90', 'P2',
    "The probe's walk of an unlent captured callee records its `storesBelow` (A3-86 a: `CalleeStoresBelow`, read at the probe's own calls), but a walked callee that hands the pointer on to a callee of its own does not carry that callee's `storesBelow` up. `Call` maps a LENT callee's `storesBelow` transitively (A3-82) and a nested walk's thunk to a lent target (round 11), but in a nested walk (`mNested`) a call or tail jump to an unlent callee only maps its frame words (`MapCalleeWords(CalleeFrameWrites(target))`), and a call it cannot name (`jsr @r5`, a callback; a cycle or an exhausted budget, `kUnwalked`) maps nothing for `storesBelow` -- the top-level `!haveTarget` rule (a frame address in r4-r7 exposes the frame) is not applied to the nested walk. So `P -> U1 -> U2`, with U2 an unlent captured fill-backwards function (any reason: a hidden counter in r3) and U1 passing r4 on by `jsr`, by `jmp`, or by a call through a callback, leaves U1's `storesBelow` empty; P hands U1 a frame address, the engine aliases from the address up, and the read of the local after the call is folded: P is withheld (\"it calls 0x06009040, whose signature is not known\"), and its text is `return 5;` where the run returns 1. A function that is lent calls only lent functions, so only the probe's text is affected (the text of a withheld function is a P2, as A3-86 a). A one-level chain (U1 itself fills backwards) is right (A3-86 a); every longer chain is stale. Current (a, b and c alike): `xunknown4 func_0x06009000(void) { xunknown1 axStack_8 [4]; func_0x06009040(axStack_8); return 5; }`, withheld; the emulator returns 1. Expected: the local, as with one level. The chain fuzzer `tools/a3_round12/walkfuzz4.py` (P, a chain of 1 to 5 unlent callees passing r4 on by jsr, jmp or a callback in r5, the last filling backwards): chains of two or more 216 of 216 stale in three seeds, chains of one 0 of 41. The generator lends every callee it draws, so it never reaches the probe's nested walk. **Fix direction (not a fix):** in a nested walk, a call or tail jump to an unlent walked callee ORs that callee's `CalleeStoresBelow(target)` into this walk's `mStoresBelow` through the registers it was passed (as the lent branch does with `h.Origins()`), and a call it cannot name or a `kUnwalked` result claims `storesBelow` for every register that holds a value with a parameter register among its origins; the cache stores the walked callee's bits, so a cached result is complete.",
    "**a** " + cf('r12a.src', 'C2a') + " (P: `sts.l pr,@-r15 ; add #-20,r15 ; mov #5,r0 ; mov.l r0,@r15 ; mov r15,r4 ; add #16,r4 ; mov #4,r3 ; jsr U1 ; mov.l @r15,r0 ; ...`; U1: `sts.l pr,@-r15 ; jsr U2 ; lds.l @r15+,pr ; rts`; U2 reads r3). **b** (a callback) " + cf('r12a.src', 'C2b') + ". **c** (a tail jump) " + cf('r12g.src', 'C2c') + ". Controls (right): one level (`r12f.src` F4), U1 calling or tail-jumping to a LENT fill-backwards function (F2, F3: pinned in `TestArea3Round12`). Replay: `OUT=<dir> sh tools/a3_round12/run.sh r12a.src C2` ; `python3 walkfuzz4.py <seed> 100`.")

row('A3-91', 'P2',
    "Clause (d) of patch 0061 takes the output of a call a frame address was handed to for a possible frame address, but only the CALL's own output varnode (r0). A lent callee that hands the address back in any other register leaves the engine's own value for it: the register's INDIRECT after the call, which is no member of the walk. So `g: mov r4,r9 ; rts` (a register the default model keeps; the lent effects mark it changed, A3-3) or `mov r4,r1` or `mov r4,r10`, GBR (`ldc r4,gbr`), MACH (`lds r4,mach`), and the caller walks down from r9 (r1, `stc gbr,r2`, `sts mach,r2`): the walk has no base, the locals under the address are unaliased and folded. The caller is withheld (\"it uses r9 after calling 0x06009040, which is not known to return it\" -- the callee is lent and the caller uses a register the call changed), but its text is `return 5;` and the run returns 1 (the text of a withheld function, P2 as A3-86 b, which this is the other registers of). Current: `xunknown4 func_0x06009000(void) { ... do { ... *(...)(r9 - 4) ... } while (iVar != 0); return 5; }`, withheld. Expected: the local. **Fix direction (not a fix):** the registers a lent call changes (`CallEffects::preserved`, A3-3) are possible frame addresses when any input of the call is a member; the walk takes the call's output only. A diagnostic build of the review that adds every INDIRECT output of the function to the walk as an unmodeled member, before and after the stack is heritaged, leaves these texts unchanged, so the value after the call is not an INDIRECT the walk can reach and the fix is in how a changed register is modelled at the call (`LendEffects`, patch 0028), to be found by the fixer.",
    "**a** (r9) " + cf('r12e.src', 'R9') + " (g: `rts ; mov r4,r9`; the caller walks `mov #4,r1 ; L: mov.l r1,@-r9 ; dt r1 ; bf L`). **b** (r1) " + cf('r12e.src', 'R1') + ". **c** (GBR, `ldc r4,gbr` in g, `stc gbr,r2` in the caller) " + cf('r12h.src', 'GB') + ". **d** (r10) " + cf('r12h.src', 'R10') + ". Control (right, A3-86 b): g `rts ; mov r4,r0` (`r12e.src` R0). Replay: `OUT=<dir> sh tools/a3_round12/run.sh r12e.src`.")

row('A3-92', 'P2',
    "The hand-back rule of A3-21, A3-39 and A3-70 -- a function that writes a word of its caller's frame is withheld, and a probe walk that hands its caller's frame on exposes the stack words -- recognises the address by exact forms: `Value::AtOrAboveEntry()` is an exact stack address at or above the entry r15, or a stack address plus an index carrying a base or `callerHigh`. The round 11 principle (a value is a possible frame address when the stack pointer is among its origins by any data path) was applied to `storesBelow` and the exposure at a call, not to this test. An address of the caller's frame that has been through an op the interpreter does not track (a swap pair, a mask `and #-4`, a shift pair: `Value::From(origins)`, no base, `callerHigh` false) is not at or above the entry r15 to `Store`, `Call` (`Get(s, r).AtOrAboveEntry()` for the registers a lent callee stores through) or the nested walker's `handsFrame` (`MapCalleeWords`). So (a) a callee that writes the word at its entry r15 (the caller's outgoing slot) through `mov r15,r1 ; swap.w r1,r1 ; swap.w r1,r1 ; mov.l r2,@r1` is lent `void g(void)` (`stores=04000000`), where the same store through the exact `r15` is withheld (A3-21); (b) the compiled-looking mask (`mov r15,r1 ; add #4,r1 ; mov #-4,r3 ; and r3,r1`) is the same; (c) a lent f that hands a laundered address of ITS caller's slot to a lent writer h is lent (A3-39 b withholds it for an exact address); (d) the probe: an unlent U1 that hands a laundered copy of its entry r15 to an unlent U2 that writes through r4 leaves the top caller's outgoing slot unexposed. The caller reads its slot back after the call and prints the value it stored before it: lent (a, b, c) or withheld (d), `return 5;` where the run returns 7. Hand-written only (compiled code owns its outgoing argument slots), as A3-21 and A3-39, hence P2. Expected: the callee withheld as the exact form is (a to c), the slot exposed with the note (d), or the local read (`return axStack_10[0];`). **Fix direction (not a fix):** keep the `callerHigh` flag (and a non-negative `stackBase`) through the ops that build `Value::From(origins)` from an operand that has it, so a laundered address of the caller's frame stays flagged while a laundered address of the function's own locals (a mask for alignment, compiled) does not; withholding on every no-base value of stack origin would withhold the aligned local buffers of compiled code.",
    "**a** " + cf('r12k.src', 'S3a') + " (g: `mov r15,r1 ; swap.w r1,r1 ; swap.w r1,r1 ; mov #7,r2 ; mov.l r2,@r1 ; rts ; nop`; the caller: `sts pr,r8 ; add #-16,r15 ; mov #5,r0 ; mov.l r0,@r15 ; jsr g ; mov.l @r15,r0 ; ...`). **b** (the entry r15 + 4 through a mask) " + cf('r12k.src', 'S3c') + ". **c** (a lent writer h at 0x06009080 `{ 0xE207, 0x000B, 0x2422, 0x0009 }`, f at 0x06009040 lent) " + cf('r12k.src', 'S3d') + ". **d** (the probe; U1 at 0x06009040, U2 at 0x06009080 reads r3, neither lent) " + cf('r12l.src', 'S3f') + ". Controls (right): the exact address, `r12k.src` S3b (g withheld), S3e (f withheld), `r12l.src` S3g. Replay: `OUT=<dir> sh tools/a3_round12/run.sh r12k.src` (and r12l).")

row('A3-93', 'P2',
    "A lent callee that stores through a pointer is assumed not to write its caller's saved registers, so `Clobber(..., spare)` leaves the slots that hold a saved register's entry value (`SavedRegister`: r8-r14, GBR, VBR, PR) unless the pointer is an exact frame address handed in a register it stores through (`exact`: `h.kind == Value::Sp`, A3-24, A3-42). The same laundering that hid the address from the other rules hides it here: a copy of r15 that has been through a swap pair is `Value::Fuzzy` with the stack origin and no base, not in `exact`, so the lent writer h is taken to leave the slot of the pushed r14 alone, f (`mov.l r14,@-r15 ; mov r15,r4 ; swap.w ×2 ; jsr h ; mov.l @r15+,r14`) is lent with r14 in `preserved` (0x003FFFE9, bit 14 set) though h overwrites the slot and f pops 7 into r14, and the caller that holds a constant in r14 across the call prints it (`return 5;`, the code returns 7). The exact copy is right (f's `preserved` has no bit 14, the caller is withheld \"it uses r14 after calling\"). Hand-written only (a pointer to a saved register's own slot), as A3-24's exact case, hence P2. Current: f lent (`void func_0x06009040(void)`, preserved 0x003FFFE9); the caller `xunknown4 func_0x06009000(void) { func_0x06009040(); return 5; }`-like, lent; emulator 7. Expected: f's r14 not preserved, the caller withheld or reading `extraout_r14`. **Fix direction (not a fix):** a possible frame address (any value with the stack among its origins) in a register a lent callee stores through is `exact` for every slot -- the spare exists for pointers to locals, and a laundered one is no more a pointer to a local than to a saved slot; the cost is that functions that pass an aligned local buffer to a lent writer lose the sparing and are withheld by the preserved-register rule, to be measured on the corpora.",
    cf('r12m.src', 'S4a') + " (the caller: `sts pr,r8 ; mov #5,r14 ; jsr f ; mov r14,r0 ; lds r8,pr ; rts`; f at 0x06009040 `sts.l pr,@-r15 ; mov.l r14,@-r15 ; mov r15,r4 ; swap.w r4,r4 ; swap.w r4,r4 ; jsr h ; mov.l @r15+,r14 ; lds.l @r15+,pr ; rts`; h at 0x06009080 `mov #7,r2 ; rts ; mov.l r2,@r4`). Control (right): `r12m.src` S4b (the exact copy). Replay: `OUT=<dir> sh tools/a3_round12/run.sh r12m.src`.")

row('A3-94', 'P2',
    "The struct-return convention (A3-4, A3-9: a callee that is not lent may read r2, the address of a returned structure, and write through it) declares an address of a local in r2 at an unlent call (`NoteFrameEscape(s, 2, true)`), but `NoteFrameEscapeOf` returns for a value with no base: `const int64_t base = v.Base(); if (base == kNoBase) return;`. The round 11 fix reasoned that such a value is covered by the `storesBelow` loop and the engine's escape analysis, which holds for r4-r7 and a lent callee; r2 is no input of the call, so neither sees it. A frame address in r2 that has been through a swap pair or a mask (`mov r15,r2 ; mov #-4,r3 ; and r3,r2`: the aligned local aggregate) is not declared and the callee's write through r2 is taken for none: the read after the call is folded to the value stored before it. The caller is withheld (\"it calls 0x06009040, whose signature is not known\"); its text is `return 5;` where the run returns 7 (P2 as A3-4, A3-9). The exact address is right. **Fix direction (not a fix):** in the probe only (a withheld function's text; the over-exposure the round 11 fix avoided was for a lent callee and an idiom modelled as a call), a no-base value of stack origin in r2 at an unlent call declares the host alias from the frame's lowest slot.",
    "**a** (a swap pair) " + cf('r12n.src', 'S5a') + " (g at 0x06009040: `mov #7,r1 ; rts ; mov.l r1,@r2`, not lent). **b** (the mask) " + cf('r12n.src', 'S5c') + ". Control (right): `r12n.src` S5b (the exact address). Replay: `OUT=<dir> sh tools/a3_round12/run.sh r12n.src`.")

if __name__ == '__main__':
    print('\n'.join(rows))
